'use strict';
const $=id=>document.getElementById(id);
const NS='http://www.w3.org/2000/svg';
const SYMBOLS={quarter:{label:'Quarter note',beats:1},eighths:{label:'Paired eighths',beats:1},half:{label:'Half note',beats:2},quarterRest:{label:'Quarter rest',beats:1},halfRest:{label:'Half rest',beats:2},eighth:{label:'Single eighth',beats:.5},eighthRest:{label:'Eighth rest',beats:.5},threeEighths:{label:'Three eighths',beats:1.5},dottedQuarter:{label:'Dotted quarter',beats:1.5},dottedQuarterRest:{label:'Dotted quarter rest',beats:1.5},dottedHalf:{label:'Dotted half',beats:3}};
const METERS={'2/4':{top:2,bottom:4,length:2,pulse:1,pulses:2,label:'Simple duple'},'3/4':{top:3,bottom:4,length:3,pulse:1,pulses:3,label:'Simple triple'},'4/4':{top:4,bottom:4,length:4,pulse:1,pulses:4,label:'Simple quadruple'},'6/8':{top:6,bottom:8,length:3,pulse:1.5,pulses:2,label:'Compound duple'}};
const meterInfo=(p=page())=>METERS[p.meter||'4/4'];
const isRest=type=>type.toLowerCase().includes('rest');
const freshPage=()=>({beats:4,notes:[],strokes:[],undo:[],redo:[]});
const state={page:'rhythm',tool:'notes',symbol:'quarter',color:'#19283f',size:6,pages:{rhythm:{...freshPage(),meter:'4/4',measures:1},treble:freshPage(),bass:freshPage(),pitch:{...freshPage(),key:'Bb',showNames:false,visible:[-1,0,1,2,3,4,5,6,7],active:null}}};
let uid=0,gesture=null,toastTimeout,confirmAction=null;
const page=()=>state.pages[state.page];
const clone=v=>JSON.parse(JSON.stringify(v));
const snapshot=()=>{const {undo,redo,...data}=page();return clone(data)};
function commit(before){page().undo.push(before);if(page().undo.length>60)page().undo.shift();page().redo=[];updateControls()}
function history(which){if(gesture)return;const p=page();if(!p[which].length)return;const prev=p[which].pop();p[which==='undo'?'redo':'undo'].push(snapshot());Object.assign(p,prev);render()}
function notify(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('visible'),2800)}
function glyph(name,x,y,width,height){const g=GLYPHS[name],b=g.bounds,s=Math.min(width/(b[2]-b[0]),height/(b[3]-b[1]));return `<path fill="currentColor" d="${g.path}" transform="translate(${x-(b[0]+b[2])*s/2} ${y+(b[1]+b[3])*s/2}) scale(${s} ${-s})"/>`}
function symbolMarkup(type,x=0,y=0,scale=1,down=false){let shape='';const head=(hx,hy,open=false)=>`<ellipse cx="${hx}" cy="${hy}" rx="13" ry="9" transform="rotate(-20 ${hx} ${hy})" ${open?'fill="white" stroke="currentColor" stroke-width="3.5"':'fill="currentColor"'}/>`;
 if(['quarter','half','dottedQuarter','dottedHalf','eighth'].includes(type)){shape=head(0,0,type==='half'||type==='dottedHalf')+`<path d="M${down?-11:11} 0v${down?61:-61}" stroke="currentColor" stroke-width="3.5"/>`;if(type==='dottedQuarter'||type==='dottedHalf')shape+='<circle cx="24" cy="-11" r="4.5" fill="currentColor"/>';if(type==='eighth')shape+=`<path d="${down?'M-11 61C-12 39-43 34-26 13C-33 40-6 32-11 61Z':'M11 -61C12 -39 43 -34 26 -13C33 -40 6 -32 11 -61Z'}" fill="currentColor"/>`}
 else if(type==='eighths'){shape=head(-17,0)+head(17,0)+`<path d="M${down?-28:-6} 0v${down?60:-60}m34 ${down?-60:60}v${down?60:-60}" stroke="currentColor" stroke-width="3.5"/><path d="M${down?-30:-8} ${down?51:-61}h38v10h-38Z" fill="currentColor"/>`}
 else if(type==='threeEighths'){for(const dx of [-27,0,27])shape+=head(dx,0)+`<path d="M${dx+(down?-11:11)} 0v${down?60:-60}" stroke="currentColor" stroke-width="3.5"/>`;shape+=`<path d="M${down?-40:-18} ${down?51:-61}h58v10h-58Z" fill="currentColor"/>`}
 else if(type==='quarterRest'||type==='dottedQuarterRest'){shape=glyph('quarterRest',0,-24,28,71);if(type==='dottedQuarterRest')shape+='<circle cx="24" cy="-27" r="4.5" fill="currentColor"/>'}
 else if(type==='eighthRest')shape=glyph('eighthRest',0,-15,35,54);
 else if(type==='halfRest')shape='<path d="M-25 0h50" stroke="currentColor" stroke-width="2"/><rect x="-17" y="-13" width="34" height="13" fill="currentColor"/>';
 return `<g transform="translate(${x} ${y}) scale(${scale})">${shape}</g>`}
function icon(type){return `<svg viewBox="-48 -72 96 98" aria-hidden="true">${symbolMarkup(type)}</svg>`}
function init(){
 $('rhythm-icon').innerHTML=icon('eighths');['treble','bass'].forEach(k=>$(k+'-icon').innerHTML=`<svg viewBox="0 0 24 30">${glyph(k,12,15,22,29)}</svg>`);
 document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>switchPage(b.dataset.page)));
 document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));
 document.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>{state.color=b.dataset.color;setTool('pen')}));
 document.querySelectorAll('[data-measures]').forEach(b=>b.addEventListener('click',()=>changeRhythmConfig(page().meter,+b.dataset.measures)));
 $('rhythm-meter').addEventListener('change',e=>changeRhythmConfig(e.target.value,page().measures));
 $('palette').addEventListener('pointerdown',paletteDown);$('palette').addEventListener('click',e=>{const b=e.target.closest('[data-symbol]');if(b){state.symbol=b.dataset.symbol;setTool('notes')}});
 $('pen-size').addEventListener('change',e=>{state.size=+e.target.value;setTool('pen')});
 $('board').addEventListener('pointerdown',boardDown);document.addEventListener('pointermove',pointerMove,{passive:false});document.addEventListener('pointerup',pointerUp);document.addEventListener('pointercancel',cancelGesture);window.addEventListener('blur',cancelGesture);
 $('board').addEventListener('keydown',e=>{if(state.page==='pitch'){pitchKeyDown(e);return}const target=e.target.closest('[data-position]');if(target&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const beat=+target.dataset.position;if(state.tool==='eraser'){const note=page().notes.find(n=>beat>=n.beat&&beat<n.beat+SYMBOLS[n.type].beats);if(note){const before=snapshot();page().notes=page().notes.filter(n=>n.id!==note.id);commit(before);renderNotes()}}else placeNote(state.symbol,{beat,y:340})}});
 $('undo').addEventListener('click',()=>history('undo'));$('redo').addEventListener('click',()=>history('redo'));
 $('clear').addEventListener('click',()=>{if(!page().notes.length&&!page().strokes.length&&page().active==null)return;ask('Clear this page?',state.page==='pitch'?'Drawings and the highlighted pitch will be cleared. Your pitch stack stays. You can undo this.':'The notes and drawings on this page will be removed. You can undo this.','Clear page',()=>{const before=snapshot();page().notes=[];page().strokes=[];if(state.page==='pitch')page().active=null;commit(before);render()})});
 $('confirm-dialog').addEventListener('close',()=>{if($('confirm-dialog').returnValue==='confirm'&&confirmAction)confirmAction();confirmAction=null});
 $('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else notify('Use your browser’s fullscreen option.')}catch{notify('Use your browser’s fullscreen option.')}});
 document.addEventListener('fullscreenchange',()=>{const full=!!document.fullscreenElement;$('fullscreen').setAttribute('aria-label',full?'Exit fullscreen':'Enter fullscreen');$('fullscreen').title=full?'Exit fullscreen':'Enter fullscreen'});
 document.addEventListener('keydown',keyHandler);initPitchStack();render();registerTools();
}
function ask(title,description,label,action){if(gesture)cancelGesture();$('dialog-title').textContent=title;$('dialog-description').textContent=description;document.querySelector('.dialog-confirm').textContent=label;confirmAction=action;$('confirm-dialog').returnValue='cancel';$('confirm-dialog').showModal()}
function switchPage(name){if(!state.pages[name])return;cancelGesture();state.page=name;render()}
function setTool(tool){cancelGesture();state.tool=tool;updateControls()}
function paletteTypes(p=page(),pageName=state.page){if(pageName!=='rhythm')return ['quarter','eighths','half','quarterRest','halfRest'];return p.meter==='6/8'?['dottedQuarter','threeEighths','quarter','eighth','eighths','dottedQuarterRest','quarterRest','eighthRest']:['quarter','eighths','half','quarterRest','halfRest',...(meterInfo(p).length>=3?['dottedHalf']:[]),'eighth','eighthRest']}
function durationLabel(type){const length=SYMBOLS[type].beats;if(state.page==='rhythm'&&page().meter==='6/8')return length===1.5?'1 beat · 3 eighths':length*2+' '+(length===.5?'eighth':'eighths');return length===.5?'½ beat':length+' '+(length===1?'beat':'beats')}
function renderPalette(){const types=paletteTypes();if(!types.includes(state.symbol))state.symbol=state.page==='rhythm'&&page().meter==='6/8'?'dottedQuarter':'quarter';$('palette').innerHTML=types.map(key=>`<button class="symbol-card ${key===state.symbol?'active':''}" data-symbol="${key}" aria-label="${SYMBOLS[key].label}, ${durationLabel(key)}" aria-pressed="${key===state.symbol}"><span class="symbol-graphic">${icon(key)}</span><span><span class="symbol-name">${SYMBOLS[key].label}</span><span class="symbol-duration">${durationLabel(key)}</span></span></button>`).join('');$('palette').classList.toggle('expanded-palette',state.page==='rhythm')}
function rhythmPlacement(type,position,p,notes=p.notes,ignoreId){if(!SYMBOLS[type]||!paletteTypes(p,'rhythm').includes(type))return {ok:false,message:'Choose a symbol from this meter’s palette.'};const length=SYMBOLS[type].beats,m=meterInfo(p),end=position+length;if(!Number.isFinite(position)||position<0||!Number.isInteger(position*2)||end>p.beats)return {ok:false,message:'That symbol needs more open space.'};if(Math.floor(position/m.length)!==Math.floor((end-0.001)/m.length))return {ok:false,message:'Keep the symbol inside one measure.'};if(p.meter==='6/8'&&Math.floor(position/m.pulse)!==Math.floor((end-0.001)/m.pulse))return {ok:false,message:'Keep each group inside one dotted-quarter beat.'};if(notes.some(n=>n.id!==ignoreId&&position<n.beat+SYMBOLS[n.type].beats&&end>n.beat))return {ok:false,message:'That space is occupied. Move or erase the symbol first.'};return {ok:true}}
function changeRhythmConfig(meter,measures){if(!METERS[meter]||![1,2].includes(measures)||state.page!=='rhythm')return;if(page().meter===meter&&page().measures===measures)return;cancelGesture();const target={...page(),meter,measures,beats:METERS[meter].length*measures};const kept=page().notes.filter(n=>rhythmPlacement(n.type,n.beat,target,[],n.id).ok),removed=page().notes.length-kept.length;const apply=()=>{const before=snapshot();Object.assign(page(),{meter,measures,beats:target.beats,notes:kept});commit(before);render()};$('rhythm-meter').value=page().meter;if(removed)ask('Change the rhythm layout?',`${removed} ${removed===1?'symbol does':'symbols do'} not fit the new meter or length and will be removed. Drawings stay. You can undo this.`,'Change layout',apply);else apply()}
// Retain the original 4/8-quarter-beat shortcut for existing callers.
function changeBeats(beats){if([4,8].includes(beats))changeRhythmConfig('4/4',beats/4)}
function updateControls(){
 document.querySelectorAll('[data-page]').forEach(b=>{const active=b.dataset.page===state.page;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});
 document.querySelectorAll('[data-tool]').forEach(b=>{const active=b.dataset.tool===state.tool;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});
 document.querySelectorAll('[data-color]').forEach(b=>{const active=b.dataset.color===state.color;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});
 document.querySelectorAll('[data-symbol]').forEach(b=>{const active=b.dataset.symbol===state.symbol&&state.tool==='notes';b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});
 document.querySelectorAll('[data-measures]').forEach(b=>{const active=+b.dataset.measures===page().measures;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});
 $('undo').disabled=!page().undo.length;$('redo').disabled=!page().redo.length;$('clear').disabled=!page().notes.length&&!page().strokes.length&&page().active==null;
 $('board').classList.toggle('pen-mode',state.tool==='pen');$('board').classList.toggle('eraser-mode',state.tool==='eraser');
 $('mode-hint').textContent=state.tool==='pen'?'Draw anywhere on the board.':state.tool==='eraser'?'Swipe over a note or drawing to erase it.':state.page==='pitch'?'Point to a syllable, or slide between pitches to lead the band.':state.page==='rhythm'?'Select a symbol, then tap a beat. Or drag it onto the line.':'Drag a symbol to a line or space. Use Pen to draw freely.';
 if(state.page==='rhythm')$('rhythm-meter').value=page().meter;
 const used=page().notes.reduce((sum,n)=>sum+SYMBOLS[n.type].beats,0);$('beat-progress').textContent=state.page==='rhythm'&&page().meter==='6/8'?`${used*2} / ${page().beats*2} eighths · ${page().measures*2} beats`:`${used} / ${page().beats} beats`;$('beat-progress').classList.toggle('complete',used===page().beats);$('beat-progress').hidden=state.page!=='rhythm'&&state.page!=='pitch';if(state.page==='pitch'){$('beat-progress').textContent=page().active===null?'Tap a pitch':pitchLabel(page().active)+(page().showNames?' · '+pitchNames()[page().active]:'');$('beat-progress').classList.remove('complete')}
}
function render(){
 const rhythm=state.page==='rhythm',pitch=state.page==='pitch';
 $('board-title').textContent=pitch?'Pitch stack':rhythm?'Build a rhythm':state.page==='treble'?'Treble-clef whiteboard':'Bass-clef whiteboard';
 $('page-eyebrow').textContent=pitch?'SOLFÈGE STUDIO':rhythm?'RHYTHM LAB':'STAFF STUDIO';$('beat-options').hidden=!rhythm;$('staff-badge').hidden=rhythm;$('staff-badge').textContent=pitch?'Concert do = '+KEY_LABELS[page().key]:'5-line staff';
 $('symbols-panel').hidden=pitch;$('pitch-settings').hidden=!pitch;document.querySelector('.app').classList.toggle('pitch-page',pitch);
 $('pointer-label').textContent=pitch?'Point':'Notes';$('pointer-tool').title=pitch?'Point to pitches (V)':'Place or move notes (V)';$('pointer-tool').setAttribute('aria-label',pitch?'Point to pitches':'Place or move notes');
 $('page-hint').textContent=pitch?'Higher pitches at the top. Follow the solfège in any key.':rhythm?`${meterInfo().label} · ${meterInfo().pulses} ${meterInfo().pulse===1.5?'dotted-quarter':'quarter-note'} beats per measure.`:'Place notes on lines and spaces, or write your own music.';$('palette-tip').textContent=rhythm?(page().meter==='6/8'?'Feel two beats: 1 la li, 2 la li. Each beat holds three eighth notes.':'Numbers mark beats; & marks the halfway point. Notes stay within the barlines.'):'Notes snap to lines and spaces. Draw freely with the pen.';
 $('board').setAttribute('aria-label',pitch?'Solfège pitch stack, high do down to low ti. Select Point to highlight pitches or Pen to draw.':rhythm?'One-line rhythm staff. Select a symbol and tap a beat, or use the pen to draw.':`${state.page} clef, five-line staff. Drag symbols to lines and spaces, or use the pen to draw.`);
 $('board').setAttribute('viewBox',pitch&&window.matchMedia('(max-width:560px)').matches?'0 0 500 700':'0 0 1200 700');if(pitch)syncPitchSettings();else renderPalette();renderGrid();renderNotes();renderInk();updateControls();
}
const layout=()=>({start:150,end:1130,width:980/page().beats,y:340});
const beatX=beat=>layout().start+(beat+.25)*layout().width;
function positionLabel(pos,p=page()){const m=meterInfo(p),within=pos%m.length,measure=Math.floor(pos/m.length)+1,beat=Math.floor(within/m.pulse)+1;return `measure ${measure}, beat ${beat}${m.pulse===1.5?', eighth '+(Math.round((within%m.pulse)*2)+1):within%1?', offbeat':''}`}
function rhythmGrid(){const p=page(),m=meterInfo(),l=layout();let html='';for(let i=0;i<p.beats/m.pulse;i++){const x=l.start+i*m.pulse*l.width;html+=`<rect x="${x+3}" y="182" width="${m.pulse*l.width-6}" height="304" rx="14" fill="${i%m.pulses===0?'#ecf2ff':'#f8faff'}" pointer-events="none"/>`}
 for(let slot=0;slot<p.beats*2;slot++){const pos=slot/2,x=l.start+pos*l.width,cx=x+l.width/4,within=pos%m.length,sub=Math.round((within%m.pulse)*2),number=Math.floor(within/m.pulse)+1,count=sub===0?number:m.pulse===1.5?(sub===1?'la':'li'):'&';html+=`<g><rect class="beat-target" data-position="${pos}" tabindex="0" role="button" aria-label="${positionLabel(pos)}. Place the selected symbol." x="${x}" y="182" width="${l.width/2}" height="304" fill="transparent"/><path d="M${cx} 211v225" stroke="#dde5f1" stroke-width="1.2" stroke-dasharray="3 9" pointer-events="none"/><text x="${cx}" y="477" fill="${sub===0?'#465d83':'#8898b0'}" font-size="${sub===0?22:17}" font-weight="${sub===0?700:500}" text-anchor="middle" pointer-events="none">${count==='&'?'&amp;':count}</text></g>`}
 html+='<path d="M132 340H1140M132 313v54M1140 313v54" stroke="#526078" stroke-width="2.5" fill="none" pointer-events="none"/>';for(let bar=1;bar<p.measures;bar++){const x=l.start+bar*m.length*l.width;html+=`<path d="M${x} 307v66" stroke="#526078" stroke-width="3" pointer-events="none"/>`}
 html+=`<g fill="#21334e" font-family="Georgia,serif" font-size="39" font-weight="700" text-anchor="middle" pointer-events="none"><text x="92" y="329">${m.top}</text><text x="92" y="368">${m.bottom}</text></g>`;for(let bar=0;bar<p.measures;bar++)html+=`<text x="${l.start+(bar+.5)*m.length*l.width}" y="154" text-anchor="middle" fill="#8694aa" font-size="15" letter-spacing="1.5" pointer-events="none">MEASURE ${bar+1}</text>`;return html}
function renderGrid(){if(state.page==='pitch'){renderPitchGrid();return}let html='';if(state.page==='rhythm'){
 html=rhythmGrid();
 }else{for(let i=0;i<5;i++)html+=`<path d="M60 ${270+i*35}H1140" stroke="#57667d" stroke-width="2.3" fill="none"/>`;html+='<path d="M60 270v140M1140 270v140" stroke="#57667d" stroke-width="2.3"/>';html+=`<g style="color:#172740" pointer-events="none">${state.page==='treble'?glyph('treble',112,340,90,245):glyph('bass',119,320,87,101)}</g>`}
 $('grid-layer').innerHTML=html;
}
function noteX(n){return state.page==='rhythm'?beatX(n.beat):n.x}
function rhythmSymbol(type,position,color='#172740'){const x=beatX(position),y=340,scale=1.05;const count=type==='eighths'?2:type==='threeEighths'?3:0;if(!count)return `<g style="color:${color}">${symbolMarkup(type,x,y,scale)}</g>`;const step=layout().width/2;let body='';for(let i=0;i<count;i++)body+=symbolMarkup('quarter',x+i*step,y,scale);body+=`<rect x="${x+10}" y="${y-64}" width="${(count-1)*step+3}" height="11" fill="currentColor"/>`;return `<g style="color:${color}">${body}</g>`}
function renderNotes(){let html='';for(const n of page().notes){const rhythm=state.page==='rhythm',x=noteX(n),y=rhythm?340:n.y,group=n.type==='eighths'?2:n.type==='threeEighths'?3:1;let ledgers='';if(!rhythm&&!isRest(n.type)){if(y<270)for(let yy=235;yy>=y;yy-=35)ledgers+=`<path d="M${x-24} ${yy}h48" stroke="#57667d" stroke-width="2"/>`;if(y>410)for(let yy=445;yy<=y;yy+=35)ledgers+=`<path d="M${x-24} ${yy}h48" stroke="#57667d" stroke-width="2"/>`}
 const hitWidth=rhythm?Math.max(40,(group-1)*layout().width/2+40):90;
 html+=`<g class="note" data-note="${n.id}" role="img" aria-label="${SYMBOLS[n.type].label}${rhythm?', '+positionLabel(n.beat):''}" style="color:#172740">${ledgers}<rect x="${x-(rhythm?20:45)}" y="${y-86}" width="${hitWidth}" height="${rhythm?112:165}" fill="transparent"/>${rhythm?rhythmSymbol(n.type,n.beat):symbolMarkup(n.type,x,y+(n.type==='quarterRest'?27.6:0),1.15,y<=340&&!isRest(n.type))}</g>`;
 if(rhythm&&group===1&&SYMBOLS[n.type].beats>.5){const endX=beatX(n.beat+SYMBOLS[n.type].beats-.5);html+=`<path d="M${x+16} 409H${endX}" fill="none" stroke="#bdcce4" stroke-width="2" stroke-dasharray="4 5" pointer-events="none"/>`}}
 $('note-layer').innerHTML=html;updateControls();
}
function strokeMarkup(s){if(s.points.length===1)return `<circle cx="${s.points[0][0]}" cy="${s.points[0][1]}" r="${s.width/2}" fill="${s.color}"/>`;return `<polyline points="${s.points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${s.color}" stroke-width="${s.width}" stroke-linecap="round" stroke-linejoin="round"/>`}
function renderInk(){ $('ink-layer').innerHTML=page().strokes.map(strokeMarkup).join('');$('ink-layer').setAttribute('pointer-events','none') }
function coords(event){const point=$('board').createSVGPoint();point.x=event.clientX;point.y=event.clientY;const matrix=$('board').getScreenCTM();if(!matrix)return{x:-1,y:-1};const p=point.matrixTransform(matrix.inverse());return{x:p.x,y:p.y}}
function inside(p){return p.x>=0&&p.x<=1200&&p.y>=0&&p.y<=700}
function candidate(p,type){if(state.page==='pitch'||!inside(p))return null;if(state.page==='rhythm'){const l=layout();if(p.x<l.start||p.x>l.end||p.y<160||p.y>510)return null;return {beat:Math.min(page().beats-.5,Math.floor((p.x-l.start)/l.width*2)/2),y:340}}
 if(p.x<185||p.x>1100||p.y<165||p.y>510)return null;return{x:Math.round(p.x/10)*10,y:type.includes('Rest')?340:Math.round((p.y-270)/17.5)*17.5+270,beat:0}}
function canPlace(type,c,ignoreId){if(!c)return{ok:false,message:'Drop the symbol onto the staff.'};if(state.page==='rhythm')return rhythmPlacement(type,c.beat,page(),page().notes,ignoreId);return{ok:true}}
function placeNote(type,c,ignoreId){const result=canPlace(type,c,ignoreId);if(!result.ok){notify(result.message);return false}const before=snapshot();const note={id:ignoreId||++uid,type,...c};if(ignoreId){const index=page().notes.findIndex(n=>n.id===ignoreId);if(index<0)return false;page().notes[index]=note}else page().notes.push(note);commit(before);renderNotes();return true}
function preview(type,c,ignoreId){if(!c){$('preview-layer').innerHTML='';return}const valid=canPlace(type,c,ignoreId).ok,color=valid?'#245add':'#cf3658';if(state.page==='rhythm'){const l=layout();$('preview-layer').innerHTML=`<rect x="${l.start+c.beat*l.width+3}" y="184" width="${Math.min(SYMBOLS[type].beats,page().beats-c.beat)*l.width-6}" height="300" rx="10" fill="${color}" opacity=".09"/><g opacity=".6">${rhythmSymbol(type,c.beat,color)}</g>`}else $('preview-layer').innerHTML=`<g style="color:${color}" opacity=".6">${symbolMarkup(type,c.x,c.y+(type==='quarterRest'?27.6:0),1.15,c.y<=340&&!isRest(type))}</g>`}
function paletteDown(e){if(e.button!==0||gesture)return;const button=e.target.closest('[data-symbol]');if(!button)return;e.preventDefault();const type=button.dataset.symbol;state.symbol=type;state.tool='notes';updateControls();gesture={kind:'palette',id:e.pointerId,type,startX:e.clientX,startY:e.clientY,moved:false};button.setPointerCapture(e.pointerId)}
function boardDown(e){if(e.button!==0||gesture)return;e.preventDefault();const p=coords(e);if(!inside(p))return;$('board').setPointerCapture(e.pointerId);if(state.tool==='pen'){const before=snapshot(),stroke={id:++uid,color:state.color,width:state.size,points:[[p.x,p.y]]};page().strokes.push(stroke);gesture={kind:'pen',id:e.pointerId,before,stroke};renderInk()}
 else if(state.tool==='eraser'){gesture={kind:'eraser',id:e.pointerId,before:snapshot(),changed:false,last:p};eraseAt(p)}
 else if(state.page==='pitch'){gesture={kind:'pitch',id:e.pointerId};highlightPitch(pitchAt(p))}
 else{const n=e.target.closest('[data-note]');if(n){const note=page().notes.find(x=>x.id===+n.dataset.note);gesture={kind:'move',id:e.pointerId,type:note.type,noteId:note.id,startX:e.clientX,startY:e.clientY,moved:false}}else{gesture={kind:'place',id:e.pointerId,type:state.symbol,startX:e.clientX,startY:e.clientY,moved:false};preview(state.symbol,candidate(p,state.symbol))}}}
function pointerMove(e){if(!gesture||gesture.id!==e.pointerId)return;e.preventDefault();const g=gesture,p=coords(e);
 if(g.kind==='pitch'){highlightPitch(pitchAt(p))}
 else if(g.kind==='pen'){const events=e.getCoalescedEvents?.()||[e];for(const ev of events){const q=coords(ev);if(inside(q)){const last=g.stroke.points[g.stroke.points.length-1];if(Math.hypot(q.x-last[0],q.y-last[1])>.6)g.stroke.points.push([q.x,q.y])}}renderInk()}
 else if(g.kind==='eraser'){const dist=Math.hypot(p.x-g.last.x,p.y-g.last.y),steps=Math.min(150,Math.ceil(dist/8));for(let i=1;i<=steps;i++)eraseAt({x:g.last.x+(p.x-g.last.x)*i/steps,y:g.last.y+(p.y-g.last.y)*i/steps});g.last=p}
 else{if(Math.hypot(e.clientX-g.startX,e.clientY-g.startY)>6)g.moved=true;if(g.kind==='palette'&&g.moved){const ghost=$('drag-ghost');ghost.innerHTML=icon(g.type);ghost.style.display='block';ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px'}preview(g.type,candidate(p,g.type),g.noteId)}}
function pointerUp(e){if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;gesture=null;const p=coords(e);$('drag-ghost').style.display='none';$('preview-layer').innerHTML='';if(g.kind==='pitch'){}else if(g.kind==='pen')commit(g.before);else if(g.kind==='eraser'){if(g.changed)commit(g.before)}else if(g.kind==='palette'){if(g.moved&&inside(p))placeNote(g.type,candidate(p,g.type));}else if(g.kind==='move'){if(g.moved&&inside(p))placeNote(g.type,candidate(p,g.type),g.noteId)}else if(g.kind==='place'){placeNote(g.type,candidate(p,g.type))}updateControls()}
function cancelGesture(){if(!gesture)return;const g=gesture;gesture=null;if(g.before)Object.assign(page(),g.before);$('drag-ghost').style.display='none';$('preview-layer').innerHTML='';renderNotes();renderInk();updateControls()}
function distanceToSegment(p,a,b){const dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p.x-a[0])*dx+(p.y-a[1])*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a[0]-t*dx,p.y-a[1]-t*dy)}
function eraseAt(p){if(!inside(p))return;const before=page().notes.length+page().strokes.length;page().notes=page().notes.filter(n=>{const x=noteX(n),y=state.page==='rhythm'?340:n.y;const down=state.page!=='rhythm'&&y<=340&&!isRest(n.type);const span=state.page==='rhythm'?(n.type==='eighths'?1:n.type==='threeEighths'?2:0)*layout().width/2:0;return !(p.x>x-(state.page==='rhythm'?20:44)&&p.x<x+span+(state.page==='rhythm'?20:44)&&p.y>y-(down?20:85)&&p.y<y+(down?85:20))});page().strokes=page().strokes.filter(s=>{const radius=16+s.width/2;if(s.points.length===1)return Math.hypot(p.x-s.points[0][0],p.y-s.points[0][1])>radius;for(let i=1;i<s.points.length;i++)if(distanceToSegment(p,s.points[i-1],s.points[i])<=radius)return false;return true});if(before!==page().notes.length+page().strokes.length){gesture.changed=true;renderNotes();renderInk()}}
function keyHandler(e){if($('confirm-dialog').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();history(e.shiftKey?'redo':'undo')}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();history('redo')}else if(!e.ctrlKey&&!e.metaKey&&!e.altKey){if(e.key.toLowerCase()==='p')setTool('pen');if(e.key.toLowerCase()==='v')setTool('notes');if(e.key.toLowerCase()==='e')setTool('eraser');if(e.key==='Escape')cancelGesture()}}
function rhythmReadback(){const p=state.pages.rhythm;return{meter:p.meter,measures:p.measures,beats:METERS[p.meter].pulses*p.measures,eighthSlots:p.beats*2,notes:p.notes.map(n=>({id:n.id,type:n.type,eighthIndex:n.beat*2}))}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
 register({name:'read_music_whiteboard',title:'Read the music whiteboard',description:'Read the active page, rhythms, placed notes, and drawing count.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{page:state.page,...(state.page==='rhythm'?rhythmReadback():{notes:clone(page().notes)}),drawingCount:page().strokes.length,...(state.page==='pitch'?{pitchStack:{key:page().key,visible:page().visible.map(pitchLabel),highlighted:page().active===null?null:pitchLabel(page().active),showConcertNames:page().showNames}}:{})}}});
 register({name:'place_rhythm_symbols',title:'Place rhythm symbols',description:'Place symbols on the rhythm page in a selected meter and one or two measures. eighthIndex is a zero-based eighth-note slot from the start. Refuses to remove existing work or place overlapping notes.',inputSchema:{type:'object',properties:{meter:{type:'string',enum:Object.keys(METERS)},measures:{type:'integer',enum:[1,2]},symbols:{type:'array',maxItems:16,items:{type:'object',properties:{type:{type:'string',enum:Object.keys(SYMBOLS)},eighthIndex:{type:'integer',minimum:0,maximum:15}},required:['type','eighthIndex'],additionalProperties:false}}},required:['meter','measures','symbols'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!METERS[input.meter]||![1,2].includes(input.measures)||!Array.isArray(input.symbols)||input.symbols.length>16)throw new Error('Provide a supported meter, one or two measures, and up to 16 symbols.');const target={...state.pages.rhythm,meter:input.meter,measures:input.measures,beats:METERS[input.meter].length*input.measures,notes:clone(state.pages.rhythm.notes)};for(const n of target.notes)if(!rhythmPlacement(n.type,n.beat,target,[],n.id).ok)throw new Error('Existing notes would not fit.');for(const s of input.symbols){if(!s||!Number.isInteger(s.eighthIndex))throw new Error('Use integer eighth-note slots.');const position=s.eighthIndex/2,result=rhythmPlacement(s.type,position,target);if(!result.ok)throw new Error(result.message);target.notes.push({id:++uid,type:s.type,beat:position,y:340})}switchPage('rhythm');const before=snapshot();Object.assign(page(),{meter:target.meter,measures:target.measures,beats:target.beats,notes:target.notes});commit(before);render();return rhythmReadback()}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
// Pitch stack: movable-do syllables, ordered by scale degree, never by instrument notation.
const PITCHES={'-1':'tị',0:'do',1:'re',2:'mi',3:'fa',4:'so',5:'la',6:'ti',7:'do′'};
const PITCH_DEGREES=[-1,0,1,2,3,4,5,6,7];
const KEY_LABELS={C:'C',Db:'D♭',D:'D',Eb:'E♭',E:'E',F:'F',Gb:'G♭',G:'G',Ab:'A♭',A:'A',Bb:'B♭',B:'B'};
const KEY_PC={C:0,Db:1,D:2,Eb:3,E:4,F:5,Gb:6,G:7,Ab:8,A:9,Bb:10,B:11};
const SCALE=[0,2,4,5,7,9,11,12];
const pitchLabel=i=>i===-1?'low ti':i===7?'high do':PITCHES[i];
function pitchNames(){const key=state.pages.pitch.key,letters=['C','D','E','F','G','A','B'],natural=[0,2,4,5,7,9,11],start=letters.indexOf(key[0]);return Object.fromEntries(PITCH_DEGREES.map(i=>{const offset=i===-1?-1:SCALE[i],letter=(start+i+7)%7;let difference=(KEY_PC[key]+offset-natural[letter]+12)%12;if(difference>6)difference-=12;return [i,letters[letter]+(difference>0?'♯'.repeat(difference):'♭'.repeat(-difference))]}))}
function initPitchStack(){
 window.addEventListener('resize',()=>{if(state.page==='pitch')$('board').setAttribute('viewBox',window.matchMedia('(max-width:560px)').matches?'0 0 500 700':'0 0 1200 700')});
 $('pitch-chips').innerHTML=PITCH_DEGREES.map(i=>`<button data-pitch-toggle="${i}" aria-label="${pitchLabel(i)}" aria-pressed="true">${PITCHES[i]}</button>`).join('');
 document.querySelectorAll('[data-pitch-toggle]').forEach(button=>button.addEventListener('click',()=>{const i=+button.dataset.pitchToggle,p=state.pages.pitch;const next=p.visible.includes(i)?p.visible.filter(n=>n!==i):[...p.visible,i].sort((a,b)=>a-b);if(!next.length){notify('Keep at least one pitch in the stack.');return}configurePitch({visible:next,active:next.includes(p.active)?p.active:null})}));
 document.querySelectorAll('[data-pitch-set]').forEach(button=>button.addEventListener('click',()=>configurePitch({visible:button.dataset.pitchSet==='five'?[0,1,2,3,4]:button.dataset.pitchSet==='pentatonic'?[0,1,2,4,5,7]:[...PITCH_DEGREES],active:null})));
 $('pitch-key').addEventListener('change',e=>configurePitch({key:e.target.value}));$('pitch-note-names').addEventListener('change',e=>configurePitch({showNames:e.target.checked}));
}
function configurePitch(changes){if(state.page!=='pitch')return;cancelGesture();const before=snapshot();Object.assign(page(),changes);commit(before);render()}
function syncPitchSettings(){const p=state.pages.pitch;$('pitch-key').value=p.key;$('pitch-note-names').checked=p.showNames;document.querySelectorAll('[data-pitch-toggle]').forEach(button=>{const selected=p.visible.includes(+button.dataset.pitchToggle);button.classList.toggle('active',selected);button.setAttribute('aria-pressed',selected)})}
const pitchY=i=>67+(7-i)*70;
function renderPitchGrid(){const p=state.pages.pitch,names=pitchNames();let html='<text x="246" y="26" fill="#7b8ba2" font-size="16" font-weight="600" letter-spacing="2" text-anchor="middle" pointer-events="none">HIGHER</text><text x="246" y="684" fill="#7b8ba2" font-size="16" font-weight="600" letter-spacing="2" text-anchor="middle" pointer-events="none">LOWER</text>';
 for(let i=7;i>=-1;i--){const y=pitchY(i),visible=p.visible.includes(i),active=p.active===i;html+=`<path d="M428 ${y}H1120" stroke="${visible?'#dfe7f3':'#eff2f7'}" stroke-width="1.5" stroke-dasharray="5 10" pointer-events="none"/>`;if(!visible){html+=`<path d="M220 ${y}h52" stroke="#e5ebf3" stroke-width="3" stroke-linecap="round" pointer-events="none"/>`;continue}
 html+=`<g class="pitch-row ${active?'active':''}" data-pitch="${i}" tabindex="0" role="button" aria-label="${pitchLabel(i)}${p.showNames?', concert '+names[i]:''}" aria-pressed="${active}"><rect class="pitch-row-bg" x="82" y="${y-31}" width="328" height="62" rx="15" fill="${active?'#245add':i===0||i===7?'#eaf1ff':'#f5f8fd'}" stroke="${active?'#245add':i===0||i===7?'#b8ccef':'#dce5f2'}" stroke-width="2"/><text class="pitch-syllable" x="${p.showNames?195:246}" y="${y+14}" text-anchor="middle" fill="${active?'#fff':'#193456'}" font-size="44" font-weight="700" pointer-events="none">${PITCHES[i]}</text>${p.showNames?`<text class="pitch-note-name" x="330" y="${y+8}" text-anchor="middle" fill="${active?'#fff':'#5d7394'}" font-size="25" font-weight="600" pointer-events="none">${names[i]}</text>`:''}</g>`;
 }$('grid-layer').innerHTML=html;
}
function pitchAt(p){if(p.x<82||p.x>410)return null;const i=7-Math.round((p.y-67)/70);return i>=-1&&i<=7&&Math.abs(p.y-pitchY(i))<=31&&page().visible.includes(i)?i:null}
function highlightPitch(i){if(i===null||state.page!=='pitch'||!page().visible.includes(i)||page().active===i)return;page().active=i;document.querySelectorAll('[data-pitch]').forEach(row=>{const degree=+row.dataset.pitch,active=degree===i;row.classList.toggle('active',active);row.setAttribute('aria-pressed',active);const bg=row.querySelector('.pitch-row-bg');bg.setAttribute('fill',active?'#245add':degree===0||degree===7?'#eaf1ff':'#f5f8fd');bg.setAttribute('stroke',active?'#245add':degree===0||degree===7?'#b8ccef':'#dce5f2');row.querySelector('.pitch-syllable').setAttribute('fill',active?'#fff':'#193456');row.querySelector('.pitch-note-name')?.setAttribute('fill',active?'#fff':'#5d7394')});updateControls()}
function pitchKeyDown(e){const row=e.target.closest('[data-pitch]');if(!row)return;const i=+row.dataset.pitch;if(e.key==='Enter'||e.key===' '){e.preventDefault();highlightPitch(i)}else if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();const pitches=[...page().visible].sort((a,b)=>a-b);const index=pitches.indexOf(i),next=pitches[Math.max(0,Math.min(pitches.length-1,index+(e.key==='ArrowUp'?1:-1)))];document.querySelector(`[data-pitch="${next}"]`)?.focus();highlightPitch(next)}}
init();
